import { readFileSync, writeFileSync } from 'node:fs';

const text = readFileSync('/tmp/probe_currency_symbol_table.txt', 'utf8');
const firstPass = text.split('=== SECOND PASS')[0];

const re = /CMD: .*--amount 1\.23 --currency ([A-Z]{3})\nEXIT: 0\nSTDOUT: ([^\n]*)\n/g;
const entries = [];
let m;
while ((m = re.exec(firstPass)) !== null) {
  const code = m[1];
  const out = m[2];
  const mm = /^([^\d]*)(\d+)(?:\.(\d+))?$/.exec(out);
  if (!mm) throw new Error(`cannot parse output for ${code}: ${JSON.stringify(out)}`);
  const symbol = mm[1];
  const digits = mm[3] ? mm[3].length : 0;
  entries.push([code, symbol, digits]);
}

function esc(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === "'") out += "\\'";
    else if (cp < 0x20 || cp > 0x7e) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += ch;
  }
  return out;
}

let src = `// Currency data for the moneyed/babel emulation.
// Auto-generated from the reference probe table (/tmp/probe_currency_symbol_table.txt,
// first pass: --amount 1.23 --currency XXX under LC_ALL=en_US.UTF-8).
// Each entry: [en-locale symbol, fraction digits]. Codes with no dedicated
// symbol in the en locale use the ISO code itself as the prefix.
// Note: XOF's symbol contains U+202F (narrow no-break space), matching babel.
const DATA = {
`;
for (const [code, symbol, digits] of entries) {
  src += `  ${code}: ['${esc(symbol)}', ${digits}],\n`;
}
src += `};

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(\`No currency with code \${code} is defined.\`);
    this.name = 'CurrencyDoesNotExist';
    this.code = code;
  }
}

// moneyed looks codes up case-insensitively (uppercased), and the
// CurrencyDoesNotExist message reports the uppercased code.
export function getCurrency(rawCode) {
  const code = String(rawCode).toUpperCase();
  const entry = DATA[code];
  if (!entry) throw new CurrencyDoesNotExist(code);
  return { code, symbol: entry[0], digits: entry[1] };
}

export const CURRENCY_COUNT = Object.keys(DATA).length;
`;

writeFileSync('/output/currencies.mjs', src);
console.log(`wrote ${entries.length} currencies`);
// sanity: check fraction-digit groups against the spec
const by = { 0: [], 3: [], 4: [] };
for (const [c, , d] of entries) if (d !== 2) by[d].push(c);
console.log('0 digits:', by[0].join(' '));
console.log('3 digits:', by[3].join(' '));
console.log('4 digits:', by[4].join(' '));
const specials = entries.filter(([, s]) => /[^\x00-\x7f]/.test(s) || s.includes('$') || s.length !== 3);
console.log('non-plain symbols:', specials.map(([c, s, d]) => `${c}=${JSON.stringify(s)}(${d})`).join(' '));

